        return false; // Ensure the data array is non-null and contains enough bytes.
    }

    for (int i = 0; i < len; i++) {
        if (data[i + offset] != data[i]) {
            return false; // Mismatch found.
        }
    }

    return true; // Both arrays are equivalent.
}

